const NativeURL = globalThis.URL;
const NativeURLSearchParams = globalThis.URLSearchParams;

class SimpleURLSearchParams {
    constructor(init='') {
        this._entries = [];
        let raw = String(init == null ? '' : init);
        if (raw.charAt(0) === '?') raw = raw.slice(1);
        if (!raw) return;
        for (const part of raw.split('&')) {
            if (!part) continue;
            const idx = part.indexOf('=');
            const kraw = idx >= 0 ? part.slice(0,idx) : part;
            const vraw = idx >= 0 ? part.slice(idx+1) : '';
            const k = decodeURIComponent(kraw.split('+').join(' '));
            const v = decodeURIComponent(vraw.split('+').join(' '));
            this._entries.push([k,v]);
        }
    }
    append(k,v){ this._entries.push([String(k), String(v)]); }
    get(k){ const e=this._entries.find(x=>x[0]===String(k)); return e?e[1]:null; }
    getAll(k){ return this._entries.filter(x=>x[0]===String(k)).map(x=>x[1]); }
    has(k){ return this._entries.some(x=>x[0]===String(k)); }
    set(k,v){ const key=String(k); let found=false; this._entries=this._entries.filter(x=>{ if(x[0]!==key) return true; if(found) return false; found=true; x[1]=String(v); return true; }); if(!found) this._entries.push([key,String(v)]); }
    toString(){ return this._entries.map(([k,v])=>encodeURIComponent(k)+'='+encodeURIComponent(v)).join('&'); }
    [Symbol.iterator](){ return this._entries[Symbol.iterator](); }
}

function parseHostPort(hostPort) {
    let hostname = hostPort;
    let port = '';
    if (hostname.charAt(0) === '[') {
        const end = hostname.indexOf(']');
        if (end >= 0) {
            const rest = hostname.slice(end+1);
            hostname = hostname.slice(1,end);
            if (rest.charAt(0) === ':') port = rest.slice(1);
            return {hostname, port};
        }
    }
    const idx = hostname.lastIndexOf(':');
    if (idx > -1 && hostname.indexOf(':') === idx) {
        port = hostname.slice(idx+1);
        hostname = hostname.slice(0,idx);
    }
    return {hostname, port};
}

class SimpleURL {
    constructor(input, base) {
        let s = String(input == null ? '' : input);
        if (base && !/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(s)) {
            const b = new SimpleURL(base);
            if (s.startsWith('/')) s = b.protocol + '//' + b.host + s;
            else s = b.protocol + '//' + b.host + b.pathname.replace(/[^/]*$/, '') + s;
        }
        let rest = s;
        let hash = '';
        const hi = rest.indexOf('#');
        if (hi >= 0) { hash = rest.slice(hi); rest = rest.slice(0,hi); }
        let search = '';
        const qi = rest.indexOf('?');
        if (qi >= 0) { search = rest.slice(qi); rest = rest.slice(0,qi); }
        let protocol = '';
        const pi = rest.indexOf(':');
        if (pi > 0 && /^[a-zA-Z][a-zA-Z0-9+.-]*$/.test(rest.slice(0,pi))) {
            protocol = rest.slice(0,pi+1);
            rest = rest.slice(pi+1);
        }
        let authHost = '';
        let pathname = rest;
        if (rest.startsWith('//')) {
            rest = rest.slice(2);
            const si = rest.indexOf('/');
            if (si >= 0) { authHost = rest.slice(0,si); pathname = rest.slice(si); }
            else { authHost = rest; pathname = '/'; }
        }
        const at = authHost.lastIndexOf('@');
        const hostPort = at >= 0 ? authHost.slice(at+1) : authHost;
        this.username = at >= 0 ? authHost.slice(0,at).split(':')[0] : '';
        this.password = at >= 0 ? (authHost.slice(0,at).split(':')[1]||'') : '';
        const hp = parseHostPort(hostPort);
        this.protocol = protocol;
        this.hostname = hp.hostname;
        this.port = hp.port;
        this.host = this.port ? this.hostname + ':' + this.port : this.hostname;
        this.pathname = pathname || '/';
        this.search = search;
        this.hash = hash;
        this.searchParams = new (NativeURLSearchParams||SimpleURLSearchParams)(this.search);
        this.href = this.toString();
        this.origin = this.protocol ? this.protocol + '//' + this.host : '';
    }
    toString(){ const q=this.searchParams.toString(); return this.protocol + '//' + this.host + this.pathname + (q?'?'+q:this.search) + this.hash; }
}

export const URL = NativeURL || SimpleURL;
export const URLSearchParams = NativeURLSearchParams || SimpleURLSearchParams;

// Node adds URL.canParse / URL.parse as statics; add them if the underlying
// class does not already provide them (guarded, in case a builtin is frozen).
if (typeof URL.canParse !== 'function') {
    try { URL.canParse = (input, base) => { try { new URL(input, base); return true; } catch (e) { return false; } }; } catch (e) {}
}
if (typeof URL.parse !== 'function') {
    try { URL.parse = (input, base) => { try { return new URL(input, base); } catch (e) { return null; } }; } catch (e) {}
}

export function fileURLToPath(value) {
    let text = String(value == null ? '' : value);
    if (text.startsWith('file:///')) text = text.slice(8);
    else if (text.startsWith('file://')) text = text.slice(7);
    return decodeURIComponent(text).split('/').join(String.fromCharCode(92));
}

export function pathToFileURL(path) {
    const value = String(path == null ? '' : path).split(String.fromCharCode(92)).join('/');
    const normalized = /^[A-Za-z]:\//.test(value) ? '/' + value : value;
    return new (NativeURL||SimpleURL)('file://' + normalized);
}

export function parse(value) {
    const u = new (NativeURL||SimpleURL)(String(value == null ? '' : value), 'file:///');
    return {
        protocol: u.protocol,
        slashes: true,
        host: u.host,
        hostname: u.hostname,
        port: u.port,
        pathname: u.pathname,
        search: u.search,
        hash: u.hash,
        href: u.href,
    };
}

export default { URL, URLSearchParams, fileURLToPath, pathToFileURL, parse };
